#include "dexmeguviz/dexmeguviz.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"type C line %d: %s\n",__LINE__,#x);return 1;}}while(0)
static int text(const uint16_t* p,uint64_t n,const char* s){size_t i;if(!p||n!=strlen(s))return 0;for(i=0;i<n;++i)if(p[i]!=(unsigned char)s[i])return 0;return 1;}
static const char* scan="{\"schema_version\":1,\"required_capabilities\":[\"type_uses\"],\"relation\":{\"op\":\"scan\",\"relation\":\"type_uses\",\"where\":{\"all\":[{\"opcode\":34},{\"target_descriptor\":\"Lfixture/TypeUses$Parent;\"}]}},\"max_results\":100}";
static const char* join="{\"schema_version\":1,\"required_capabilities\":[\"type_uses\"],\"relation\":{\"op\":\"join\",\"on\":\"target_ref\",\"left\":{\"op\":\"scan\",\"relation\":\"type_uses\",\"where\":{\"opcode\":34}},\"right\":{\"op\":\"scan\",\"relation\":\"type_refs\",\"where\":{\"descriptor\":\"Lfixture/TypeUses$Parent;\"}}},\"max_results\":100}";
static const char* caller="{\"schema_version\":1,\"required_capabilities\":[\"type_uses\"],\"relation\":{\"op\":\"join\",\"on\":\"caller\",\"left\":{\"op\":\"scan\",\"relation\":\"type_uses\",\"where\":{\"opcode\":34}},\"right\":{\"op\":\"scan\",\"relation\":\"method_defs\",\"where\":{\"name\":\"allocate\"}}},\"max_results\":100}";
static int run(dmg_engine* e,dmg_snapshot* snap,const char* json,unsigned count,int job){
 dmg_error error={0};dmg_query* q=NULL;dmg_result* r=NULL;dmg_query_info qi={0};dmg_relation_info_v3 info;unsigned i;
 CHECK(dmg_query_compile_json(e,(const uint8_t*)json,strlen(json),&q,&error)==DMG_OK);CHECK(dmg_query_get_info(q,&qi)==DMG_OK&&strncmp(qi.query_id,"query:v21:",10)==0);
 CHECK(dmg_query_execute(snap,q,&r,&error)==DMG_OK);memset(&info,0xa5,sizeof(info));CHECK(dmg_result_get_relation_info_v2(r,&info,sizeof(info))==DMG_UNSUPPORTED);CHECK(dmg_result_get_relation_info_v3(r,&info,sizeof(info))==DMG_OK&&info.candidates_count==count);
 for(i=0;i<count;++i){dmg_value_row_v3 v,guard;dmg_value_row_v2 old,oldguard;uint32_t witnesses=0;memset(&old,0xa5,sizeof(old));oldguard=old;CHECK(dmg_result_get_value_v2(r,i,&old,sizeof(old))==DMG_UNSUPPORTED&&!memcmp(&old,&oldguard,sizeof(old)));memset(&v,0xa5,sizeof(v));guard=v;CHECK(dmg_result_get_value_v3(r,i,&v,sizeof(v)-1)==DMG_INVALID_ARGUMENT&&!memcmp(&v,&guard,sizeof(v)));CHECK(dmg_result_get_value_v3(r,i,&v,sizeof(v))==DMG_OK);CHECK(v.value.kind==DMG_VALUE_USE&&v.value.use.relation==DMG_TYPE_USES&&v.value.use.target_domain==DMG_TARGET_TYPE_REF&&v.value.use.opcode==0x22);CHECK(text(v.target_descriptor,v.target_descriptor_length,"Lfixture/TypeUses$Parent;"));CHECK(dmg_result_get_witness_count(r,i,&witnesses)==DMG_OK&&witnesses);if(strstr(json,"\"op\":\"join\"")){uint32_t n=0;dmg_relation_link_v3 link;CHECK(dmg_result_get_link_count(r,i,&n)==DMG_OK&&n==1);CHECK(dmg_result_get_link_v3(r,i,0,&link,sizeof(link))==DMG_OK&&link.left.source_index==link.right.source_index);if(link.key==DMG_JOIN_TARGET_REF)CHECK(link.right.relation==DMG_TYPE_REFS&&link.right.local_index==v.value.use.target_index);}}
 if(job){dmg_job* h=NULL;dmg_batch* b=NULL;dmg_job_options opts={sizeof(opts),DMG_ABI_VERSION,1,2,0};dmg_relation_job_status_v3 st;unsigned got=0;CHECK(dmg_job_start(snap,q,&opts,&h,&error)==DMG_OK);for(;;){dmg_status c=dmg_job_next(h,15000,&b,&error);if(c==DMG_END_OF_STREAM)break;CHECK(c==DMG_OK&&b);CHECK(dmg_result_get_relation_info_v3(b,&info,sizeof(info))==DMG_OK);got+=info.candidates_count;dmg_batch_release(b);b=NULL;}CHECK(dmg_job_wait_relation_v2(h,15000,&st,sizeof(st))==DMG_UNSUPPORTED);CHECK(dmg_job_wait_relation_v3(h,15000,&st,sizeof(st))==DMG_OK&&st.terminal&&st.outcome.execution_status==DMG_OK&&got==count);dmg_job_release(h);}
 dmg_result_release(r);dmg_query_release(q);return 0;
}
int main(int argc,char**argv){dmg_engine* e=NULL;dmg_snapshot* snap=NULL;dmg_snapshot* dual=NULL;dmg_error err={0};FILE* f;long size;unsigned char* bytes;dmg_source_spec spec={0};dmg_source_set_options opts={sizeof(opts),DMG_ABI_VERSION,"type-uses-c",1,8,1u<<20};CHECK(argc==2);f=fopen(argv[1],"rb");CHECK(f&&fseek(f,0,SEEK_END)==0);size=ftell(f);CHECK(size>0&&fseek(f,0,SEEK_SET)==0);bytes=(unsigned char*)malloc((size_t)size);CHECK(bytes&&fread(bytes,1,(size_t)size,f)==(size_t)size);fclose(f);CHECK(dmg_engine_create(NULL,&e,&err)==DMG_OK);spec.struct_size=sizeof(spec);spec.abi_version=DMG_ABI_VERSION;spec.format=DMG_INPUT_RAW_DEX;spec.data=bytes;spec.size=(uint64_t)size;spec.slot_key="base";spec.role="base";CHECK(dmg_snapshot_open_sources(e,&spec,1,&opts,&snap,&err)==DMG_OK);{dmg_source_spec two[2]={spec,spec};two[1].slot_key="split";two[1].role="code-split";CHECK(dmg_snapshot_open_sources(e,two,2,&opts,&dual,&err)==DMG_OK);}free(bytes);CHECK(run(e,snap,scan,2,1)==0);CHECK(run(e,snap,join,2,0)==0);CHECK(run(e,snap,caller,1,0)==0);CHECK(run(e,dual,join,4,0)==0);CHECK(run(e,dual,caller,2,0)==0);dmg_snapshot_release(dual);dmg_snapshot_release(snap);dmg_engine_release(e);puts("PASS C type scan, target/caller joins, v2 rejection and Job");return 0;}
